P(('h3','6.4. Mẫu thiết kế văn phòng 90m2 không gian mở (Open Office)'))
P(('p','Không gian mở bỏ hẳn vách ngăn cố định giữa các bộ phận, chỉ giữ lại một đến hai phòng kín thực sự cần. Việc phân vùng do nội thất đảm nhiệm: bàn cụm, tủ thấp, thảm, thay đổi cao độ trần hoặc màu sàn. Với 90m², đây là phương án cho ra số chỗ ngồi cao nhất trong năm phong cách.'))
P(('lead','Ưu điểm với mặt bằng 90m²'))
P(('ul',[
  '**Nhiều chỗ ngồi nhất — lên tới 20 chỗ.** Bỏ được phần diện tích tường và hành lang phụ mà mặt bằng chia phòng buộc phải có.',
  '**Dễ đổi bố cục.** Tăng hay giảm nhân sự chỉ cần kê lại bàn, không phải đập vách — quan trọng với doanh nghiệp đang lớn.',
  '**Ánh sáng tự nhiên đi được sâu vào trong.** Không có vách chặn nên vị trí ngồi trong cùng vẫn đủ sáng.',
  '**Tăng kết nối giữa các bộ phận.** Ở quy mô dưới 20 người, cả đội nhìn thấy nhau là ưu thế vận hành.']))
P(('p','Trên 90m², phương án chia ba phòng kín cần khoảng 9 – 12m² cho riêng phần tường, vách và hành lang dẫn vào. Bỏ hết phòng kín, phần đó quay về khu làm việc chung — tương đương **thêm 3 – 4 chỗ ngồi**. Cái giá là tiếng ồn: cần trần tiêu âm hoặc tấm tiêu âm treo, chi phí khoảng 300.000 – 600.000đ/m², tức 12 – 24 triệu cho phần khu làm việc — nhỏ so với giá trị của 3 – 4 chỗ ngồi thêm. Với 90m², phương án cân bằng nhất là mở hoàn toàn khu làm việc nhưng vẫn giữ đúng một phòng họp kín tiếng.'))
P(('img','b80-20','Khu sáng tạo mở với tường ghi chú, ghế lười và bàn dùng chung (Ảnh tham khảo)'))
P(('img','b80-22','Màu thương hiệu dùng ở mảng lớn trong không gian mở để phân vùng thay cho vách (Ảnh tham khảo)'))
P(('img','b80-21','Sàn mở hoàn toàn cho số chỗ ngồi tối đa, bù lại cần trần tiêu âm và thảm để giảm ồn (Ảnh tham khảo)'))
P(('img','b80-40','Không bàn cố định, tủ khóa cá nhân thay ngăn kéo nên cùng diện tích phục vụ được nhiều người hơn (Ảnh tham khảo)'))
P(('img','a70-11','Trần để lộ hệ kỹ thuật, bàn kê thành cụm, không vách ngăn cố định (Ảnh tham khảo)'))

P(('h3','6.5. Mẫu thiết kế văn phòng 90m2 phong cách công nghiệp (Industrial)'))
P(('p','Phong cách công nghiệp giữ nguyên vẻ thô của kết cấu: trần bê tông để mộc lộ hệ ống gió và máng điện, tường gạch hoặc bê tông trần, khung thép sơn đen, sàn gỗ hoặc bê tông mài. Điểm quan trọng với văn phòng 90m2: phong cách này chỉ phát huy khi **trần cao trên 3m** — trần thấp mà để lộ hệ kỹ thuật sẽ gây cảm giác nặng và bí.'))
P(('lead','Ưu điểm với mặt bằng 90m²'))
P(('ul',[
  '**"Ăn gian" được chiều cao.** Bỏ trần thạch cao trả lại 30 – 50cm chiều cao thông thủy.',
  '**Cắt được một hạng mục thi công.** Không làm trần giả nghĩa là bớt cả phần khung xương và hoàn thiện.',
  '**Khung thép đen chia khu rất hợp.** Vách kính khung thép vừa là phong cách vừa là giải pháp phân khu cho 5 khu chức năng.',
  '**Bền, ít phải bảo trì bề mặt.** Vật liệu thô ít lộ dấu sử dụng hơn bề mặt sơn phẳng.']))
P(('p','Trần thạch cao khung xương cho 90m² thường tốn 250.000 – 400.000đ/m², tức **22,5 – 36 triệu** cho cả sàn. Bỏ trần giả và chỉ sơn hệ kỹ thuật màu tối tiết kiệm phần lớn khoản này, đồng thời trả lại 30 – 50cm chiều cao. Đổi lại, hệ điện và điều hòa phải đi gọn và thẳng hàng vì không còn chỗ giấu — hạng mục này cần chốt bản vẽ kỹ trước khi thi công.'))
P(('img','b80-02','Hộp phòng họp bằng gỗ ép dựng giữa sàn mở — tách tiếng ồn mà không xây tường (Ảnh tham khảo)'))
P(('img','b80-30','Vật liệu thô mộc kết hợp nội thất da, đủ trang trọng để tiếp khách (Ảnh tham khảo)'))
P(('img','b80-17','Gạch mộc, gác lửng khung thép và sàn gỗ sẫm tạo dấu ấn riêng cho doanh nghiệp sáng tạo (Ảnh tham khảo)'))
P(('img','b80-23','Trần để mộc giúp ăn gian chiều cao, nhưng chỉ hiệu quả khi trần cao trên 3m (Ảnh tham khảo)'))
P(('img','a70-03','Trần cao để lộ hệ kỹ thuật, khung thép và hệ cửa kính lớn (Ảnh tham khảo)'))

# ---------------- MUC 7 — HINH DANG MAT BANG ----------------
P(('h2','7. Mẫu thiết kế văn phòng 90m2 theo hình dạng mặt bằng'))
P(('p','Phong cách là thứ doanh nghiệp được chọn. Hình dạng mặt bằng thì không — nó đã có sẵn khi ký hợp đồng thuê. Ba dạng dưới đây tương ứng với ba sơ đồ ở mục 4. Với mỗi dạng, phần quan trọng nhất là **luồng khách và luồng nhân viên chạy ra sao**.'))

P(('h3','7.1. Mẫu văn phòng 90m2 mặt bằng hẹp và dài'))
P(('p','Dạng phổ biến nhất trong các tòa văn phòng cho thuê, tỷ lệ từ 1:3 đến 1:4 — với 90m² thường là 18m × 5m hoặc 20m × 4,5m. Cửa vào nằm ở một đầu, cửa sổ chạy dọc một hoặc hai mặt dài. Bố trí gần như bắt buộc: hai phòng kín ở hai đầu, khu làm việc chung ở giữa, lối đi chạy suốt theo trục dài.'))
P(('lead','Ưu điểm với mặt bằng 90m²'))
P(('ul',[
  '**Phân khu rất rõ ràng.** Khu khách một đầu, khu nội bộ đầu kia, không ai lẫn vào ai.',
  '**Mặt kính dài.** Cửa sổ chạy suốt cạnh dài nên cả hai dãy bàn đều có sáng tự nhiên.',
  '**Dễ kê bàn thẳng dãy.** Hai dãy 7 chỗ dọc trục là cách kê đơn giản và ít lãng phí góc nhất.',
  '**Phòng giám đốc và phòng họp tách xa nhau.** Tiếng họp không lọt sang phòng lãnh đạo.']))
P(('p','Theo sơ đồ 1 (18m × 5m), lối đi chính 1,2m chạy suốt 10m, chiếm khoảng 12m². Khu làm việc chung sâu 3,7m nên chỉ xếp được hai dãy bàn — cho 14 chỗ, cộng lễ tân là 15. Ít nhất trong ba dạng, dù diện tích y hệt.'))
P(('p','**Luồng đi ra sao:** đây là dạng khó nhất. Phòng họp nằm cuối mặt bằng nên khách buộc phải đi dọc hết hai dãy bàn. Cách chữa: đổi phòng họp lên sát lễ tân và đẩy phòng giám đốc xuống cuối. Nếu không đổi được vì vướng cửa sổ, thì kê một dãy tủ cao 1,6m làm lớp chắn giữa lối đi của khách và dãy bàn đầu tiên.'))
P(('img','b80-03','Phòng dài hẹp với dãy cửa sổ chạy suốt một cạnh — ánh sáng tự nhiên đều cho cả dãy bàn (Ảnh tham khảo)'))
P(('img','b80-29','Bàn kê thẳng dãy dọc trục dài, lối đi chạy suốt một bên (Ảnh tham khảo)'))
P(('img','b80-10','Hai dãy bàn đối xứng dọc trục với hệ đèn thả chạy theo chiều dài phòng (Ảnh tham khảo)'))
P(('img','b80-25','Bàn dài dùng chung bỏ được khoảng hở giữa các bàn — cách kê tiết kiệm diện tích nhất cho mặt bằng hẹp (Ảnh tham khảo)'))
P(('img','a70-10','Trần dầm gỗ để mộc kết hợp bàn dài dùng chung trong không gian kéo dài (Ảnh tham khảo)'))

P(('h3','7.2. Mẫu văn phòng 90m2 mặt bằng vuông cân xứng'))
P(('p','Mặt bằng vuông hoặc gần vuông có tỷ lệ từ 1:1 đến 1:1,3 — với 90m² thường là 9,5m × 9,5m hoặc 10m × 9m. Đây là dạng dễ quy hoạch nhất: khu làm việc chung chiếm trọn một nửa, các phòng chức năng xếp dọc một cạnh, lối đi chỉ cần một trục thẳng.'))
P(('lead','Ưu điểm với mặt bằng 90m²'))
P(('ul',[
  '**Nhiều chỗ ngồi nhất trong ba dạng.** Khu làm việc sâu trên 7m nên xếp được bốn dãy bàn thay vì hai.',
  '**Lối đi ngắn nhất.** Một trục thẳng phục vụ cả mặt bằng, không phải chạy vòng.',
  '**Hai luồng tách ngay từ cửa.** Khách rẽ trái vào lễ tân, nhân viên rẽ phải theo trục dọc.',
  '**Dễ mở rộng về sau.** Thêm một dãy bàn không phá vỡ bố cục tổng thể.']))
P(('p','Theo sơ đồ 2 (9,5m × 9,5m), khu làm việc chung sâu 7,3m. Mỗi dãy bàn cần khoảng 1,4m chiều sâu tính cả ghế, nên xếp được bốn dãy — gấp đôi dạng hẹp dài. Với bốn chỗ mỗi dãy, mặt bằng cho ra 16 chỗ, cộng lễ tân là 17, mà vẫn giữ đủ phòng giám đốc 9m², pantry 5m² và phòng họp 8 chỗ 12m².'))
P(('p','**Luồng đi ra sao:** sạch nhất về mặt số liệu. Hai luồng tách ngay ngưỡng cửa và không cắt nhau lần nào. Cái giá phải trả nằm chỗ khác: mặt bằng vuông thường chỉ có một đến hai mặt tiếp xúc cửa sổ, nên vị trí ngồi giữa sàn thiếu sáng tự nhiên — phải bù bằng hệ đèn đủ 400 – 500 lux trên mặt bàn.'))
P(('img','b80-01','Bàn kê dọc tường kính, phòng họp ốp gỗ sát lối đi — cách chia khu quen thuộc của mặt bằng vuông (Ảnh tham khảo)'))
P(('img','b80-35','Khu làm việc tập trung giữa phòng, hệ tủ và kệ dồn hết vào tường bao (Ảnh tham khảo)'))
P(('img','b80-41','Khối tủ trưng bày đặt giữa sàn vừa phân vùng vừa lưu trữ, hợp mặt bằng vuông (Ảnh tham khảo)'))
P(('img','b80-14','Điểm nhấn vàng đồng ở khu tiếp khách làm ấm mặt bằng vuông vốn nhiều tường đặc (Ảnh tham khảo)'))
P(('img','a70-21','Khu làm việc mở, tủ thấp thay vách ngăn để ánh sáng đi được vào sâu giữa sàn (Ảnh tham khảo)'))

P(('h3','7.3. Mẫu văn phòng 90m2 mặt bằng lô góc'))
P(('p','Lô góc là mặt bằng nằm ở góc tòa nhà, có hai mặt tiếp xúc cửa sổ vuông góc nhau — với 90m² thường là 12m × 7,5m. Đây là dạng sáng nhất và có giá thuê cao nhất. Bài toán riêng của nó là điểm giao hai bức tường: nếu không xử lý, góc này thành góc chết.'))
P(('lead','Ưu điểm với mặt bằng 90m²'))
P(('ul',[
  '**Ánh sáng tự nhiên tốt nhất.** Hai mặt kính nghĩa là sáng gần như cả ngày, ít phải bật đèn.',
  '**Đủ chỗ cho một khu tiếp khách riêng.** Đây là thứ chỉ từ 90m² mới làm nổi, và lô góc là dạng hợp nhất để làm.',
  '**Luồng khách gọn nhất.** Khách ở trọn trong dải tiếp khách phía trên, không bước vào khu làm việc lần nào.',
  '**Thông gió tự nhiên tốt hơn.** Cửa sổ hai hướng cho phép tạo luồng khí đối lưu.']))
P(('p','Theo sơ đồ 3 (12m × 7,5m), lễ tân 6,6m² và khu tiếp khách 10,1m² chiếm dải trên, khu làm việc chung 40m² với ba dãy bàn 5 chỗ nằm trọn phía dưới. Kết quả 16 chỗ — nhiều hơn dạng hẹp dài một chỗ, ít hơn dạng vuông một chỗ, nhưng **là dạng duy nhất trong ba dạng mà khách không đi qua chỗ ngồi nào**.'))
P(('p','**Luồng đi ra sao:** tốt nhất trong ba dạng. Cái giá là phòng họp chỉ còn 8,1m² nên tối đa 6 chỗ, và pantry bị đẩy xuống cuối lối đi. Ngoài ra hai mặt kính đồng nghĩa ít tường đặc để kê tủ hồ sơ — hệ lưu trữ phải dồn vào một cạnh hoặc chuyển sang tủ thấp dưới bệ cửa sổ.'))
P(('img','b80-26','Góc hai mặt cửa sổ lớn dùng làm khu tiếp khách, khai thác đúng vị trí đắt giá nhất của lô góc (Ảnh tham khảo)'))
P(('img','b80-27','Khu tiếp khách đặt sát dãy cửa sổ hai mặt, tận dụng ánh sáng tự nhiên thay cho đèn (Ảnh tham khảo)'))
P(('img','b80-16','Vách kính khung thép đen ở góc phòng — giữ được tầm nhìn hai hướng khi chia phòng riêng (Ảnh tham khảo)'))
P(('img','b80-42','Trần lam gỗ và bàn màu nhấn ở khu ven cửa sổ — cách làm ấm mặt bằng nhiều kính (Ảnh tham khảo)'))
P(('img','a70-07','Đường vòm kiến trúc màu vàng và cây xanh ở khu tiếp khách tràn ngập ánh sáng tự nhiên (Nguồn: Internet)'))
